ont-size:13px;line-height:1.6">QuickGuard · Professional security staffing<br><a href="https://quickguard.uk" style="color:#0F766E">quickguard.uk</a></p></td></tr></table></td></tr></table><p style="text-align:center;font-size:13px;color:#475569">{{year}}</p></body></html>' where template_slug='accessibility_feedback' and md5(body_html)='3e61aeccb1aefc2b60e2a92b7388210b';
