update app.email_templates set body_html='<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Security Alert | QuickGuard</title></head><body style="margin:0;padding:0;background:#F1F5F9;font-family:Arial,Helvetica,sans-serif;color:#334155"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:24px 12px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#ffffff;border:1px solid #E2E8F0;border-radius:8px"><tr><td style="background:#0B1933;padding:24px 28px;border-bottom:4px solid #14B8A6"><p style="margin:0;color:#ffffff;font-size:24px;font-weight:bold">QuickGuard</p></td></tr><tr><td style="padding:28px"><h1 style="margin:0 0 20px;color:#0B1933;font-size:26px;line-height:1.3">Security Alert</h1><p style="background:#FEF2F2;color:#991B1B;padding:12px 16px;border-radius:6px;font-size:14px;font-weight:bold;margin:0 0 24px">Action or status update</p><table cellpadding="0" cellspacing="0" role="presentation" style="" width="100%"><tr style=""><td style="padding:16px 0;text-align:center"><p style="margin:8px 0 0;font-size:16px;line-height:1.65;color:#334155">Admin Password Reset Requested</p></td></tr><tr style=""><td style="padding:16px 0"><p style="font-size:16px;line-height:1.65;color:#334155">A password reset has been requested for the QuickGuard admin account. If this was you, no action is needed. If you did <strong style="">not</strong> request this, secure your account immediately.</p><div style="border:1px solid #E2E8F0;border-radius:6px;margin:20px 0;padding:20px;background:#F1F5F9;color:#334155"><h3 style="margin:0 0 16px;font-size:18px;text-transform:uppercase;line-height:1.3;color:#0B1933">Reset Details</h3><p style="margin:6px 0;font-size:16px;line-height:1.65;color:#334155"><strong style="">Account:</strong> {{email}}</p><p style="margin:6px 0;font-size:16px;line-height:1.65;color:#334155"><strong style="">Time:</strong> {{timestamp}}</p>{{ip_block}}<p style="margin:6px 0;font-size:16px;line-height:1.65;color:#334155"><strong style="">Platform:</strong> QuickGuard Admin Portal</p></div><div style="border:1px solid #E2E8F0;border-radius:6px;margin-bottom:28px;padding:20px;background:#F1F5F9;margin:20px 0;color:#334155"><p style="font-size:16px;margin:0;line-height:1.65;color:#334155">⚠️ <strong style="">If you did not request this reset</strong>, your admin credentials may be compromised.</p></div></td></tr></table></td></tr><tr><td style="padding:22px 28px;background:#F8FAFC;border-top:1px solid #E2E8F0"><p style="margin:0;color:#475569;font-size:13px;line-height:1.6">QuickGuard · Professional security staffing<br><a href="https://quickguard.uk" style="color:#0F766E">quickguard.uk</a></p></td></tr></table></td></tr></table><p style="text-align:center;font-size:13px;color:#475569">{{year}}</p></body></html>' where template_slug='admin_password_reset_alert' and md5(body_html)='4343c0f8f2840b05351fc315d913247d';
GET DIAGNOSTICS changed = ROW_COUNT;
IF changed <> 1 THEN RAISE EXCEPTION 'Template snapshot changed: admin_password_reset_alert'; END IF;
update app.email_templates set body_html='<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>🎉 Congratulations! | QuickGuard</title></head><body style="margin:0;padding:0;background:#F1F5F9;font-family:Arial,Helvetica,sans-serif;color:#334155"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:24px 12px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#ffffff;border:1px solid #E2E8F0;border-radius:8px"><tr><td style="background:#0B1933;padding:24px 28px;border-bottom:4px solid #14B8A6"><p style="margin:0;color:#ffffff;font-size:24px;font-weight:bold">QuickGuard</p></td></tr><tr><td style="padding:28px"><h1 style="margin:0 0 20px;color:#0B1933;font-size:26px;line-height:1.3">🎉 Congratulations!</h1><p style="background:#ECFDF5;color:#065F46;padding:12px 16px;border-radius:6px;font-size:14px;font-weight:bold;margin:0 0 24px">Confirmation</p><table cellpadding="0" cellspacing="0" role="presentation" style="" width="100%"><tr style=""><td style="padding:16px 0;text-align:center"><p style="font-size:16px;line-height:1.65;color:#334155">You got the job!</p></td></tr><tr style=""><td style="padding:16px 0"><p style="font-size:16px;line-height:1.65;color:#334155">Hi <strong style="">{{guard_name}}</strong>,</p><p style="font-size:16px;line-height:1.65;color:#334155"><strong style="">{{client_name}}</strong> has accepted your application for <strong style="">{{job_title}}</strong>.</p><div style="border-radius:6px;padding:20px;margin-bottom:30px;border:1px solid #E2E8F0;background:#F1F5F9;margin:20px 0;color:#334155"><p style="font-size:16px;line-height:1.65;color:#334155"><strong style="">Client:</strong> {{client_name}}</p><p style="font-size:16px;line-height:1.65;color:#334155"><strong style="">Date:</strong> {{job_date}}</p><p style="font-size:16px;line-height:1.65;color:#3