ate:</strong> £{{hourly_rate}}/hour</p></div><p style="font-size:16px;line-height:1.65;color:#334155">Your job is now confirmed. Please check your dashboard for full details and shift instructions.</p><div style="text-align:center;margin:30px 0"><a href="{{dashboard_url}}" style="display:inline-block;background:#0F766E;color:#ffffff;padding:14px 24px;border-radius:6px;font-weight:bold;font-size:16px;line-height:1.4;text-decoration:none;text-align:center">View Dashboard</a></div><p style="font-size:16px;line-height:1.65;color:#334155">If you have any questions, please contact support.</p></div></div></td></tr><tr><td style="padding:22px 28px;background:#F8FAFC;border-top:1px solid #E2E8F0"><p style="margin:0;color:#475569;font-size:13px;line-height:1.6">QuickGuard · Professional security staffing<br><a href="https://quickguard.uk" style="color:#0F766E">quickguard.uk</a></p></td></tr></table></td></tr></table></body></html>' where template_slug='guard_booking_confirmation' and md5(body_html)='7ca1026073fd563a17b04e49c8269e40';
