yle="padding:16px 0;border-bottom:1px solid #E5E7EB"><strong style="">Date:</strong></td><td style="padding:16px 0;border-bottom:1px solid #E5E7EB;text-align:right">{{payment_date}}</td></tr><tr style=""><td style="padding:16px 0;border-bottom:1px solid #E5E7EB"><strong style="">Plan:</strong></td><td style="padding:16px 0;border-bottom:1px solid #E5E7EB;text-align:right">{{subscription_plan}}</td></tr><tr style=""><td style="padding:16px 0;border-bottom:1px solid #E5E7EB"><strong style="">Period:</strong></td><td style="padding:16px 0;border-bottom:1px solid #E5E7EB;text-align:right">{{billing_period}}</td></tr><tr style=""><td style="padding:16px 0"><strong style="font-size:18px">Total:</strong></td><td style="padding:16px 0;text-align:right"><strong style="font-size:20px">£{{amount}}</strong></td></tr></table><div style="text-align:center;margin:30px 0"><a href="{{dashboard_url}}" style="display:inline-block;background:#0F766E;color:#ffffff;padding:14px 24px;border-radius:6px;font-weight:bold;font-size:16px;line-height:1.4;text-decoration:none;text-align:center">View Dashboard</a></div></td></tr></table></td></tr><tr><td style="padding:22px 28px;background:#F8FAFC;border-top:1px solid #E2E8F0"><p style="margin:0;color:#475569;font-size:13px;line-height:1.6">QuickGuard · Professional security staffing<br><a href="https://quickguard.uk" style="color:#0F766E">quickguard.uk</a></p></td></tr></table></td></tr></table></body></html>' where template_slug='payment_receipt' and md5(body_html)='fdea9ceabbba5ad2cc24d404c4530130';
