update app.email_templates set body_html='<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Support Ticket Created | QuickGuard</title></head><body style="margin:0;padding:0;background:#F1F5F9;font-family:Arial,Helvetica,sans-serif;color:#334155"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:24px 12px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#ffffff;border:1px solid #E2E8F0;border-radius:8px"><tr><td style="background:#0B1933;padding:24px 28px;border-bottom:4px solid #14B8A6"><p style="margin:0;color:#ffffff;font-size:24px;font-weight:bold">QuickGuard</p></td></tr><tr><td style="padding:28px"><h1 style="margin:0 0 20px;color:#0B1933;font-size:26px;line-height:1.3">Support Ticket Created</h1><table cellpadding="0" cellspacing="0" role="presentation" style="" width="100%"><tr style=""><td style="padding:16px 0;text-align:center"><p style="margin:8px 0 0;font-size:16px;line-height:1.65;color:#334155">We have received your request</p></td></tr><tr style=""><td style="padding:16px 0"><p style="font-size:16px;line-height:1.65;color:#334155">Hi {{customer_name}},</p><p style="font-size:16px;line-height:1.65;color:#334155">Your support ticket has been created. Our team will respond as soon as possible.</p><table cellpadding="0" cellspacing="0" style="border-radius:8px;padding:20px;margin:20px 0" width="100%"><tr style=""><td style="padding:16px 0"><strong style="">Ticket ID:</strong> #{{ticket_id}}</td></tr><tr style=""><td style="padding:16px 0"><strong style="">Subject:</strong> {{ticket_subject}}</td></tr><tr style=""><td style="padding:16px 0"><strong style="">Priority:</strong> {{ticket_priority}}</td></tr><tr style=""><td style="padding:16px 0"><strong style="">Category:</strong> {{ticket_category}}</td></tr></table><p style="font-size:16px;line-height:1.65;color:#334155">Please allow up to 24 hours for a response. For urgent matters, call us directly.</p><div style="text-align:center;margin:28px 0"><a href="{{dashboard_url}}" style="display:inline-block;background:#0F766E;color:#ffffff;padding:14px 24px;border-radius:6px;font-weight:bold;font-size:16px;line-height:1.4;text-decoration:none;text-align:center">View My Tickets</a></div></td></tr></table></td></tr><tr><td style="padding:22px 28px;background:#F8FAFC;border-top:1px solid #E2E8F0"><p style="margin:0;color:#475569;font-size:13px;line-height:1.6">QuickGuard · Professional security staffing<br><a href="https://quickguard.uk" style="color:#0F766E">quickguard.uk</a></p></td></tr></table></td></tr></table><p style="text-align:center;font-size:13px;color:#475569">{{year}}</p></body></html>' where template_slug='support_ticket_created' and md5(body_html)='efbc31611eafcd3cd1b8a017d45b2d8f';
GET DIAGNOSTICS changed = ROW_COUNT;
IF changed <> 1 THEN RAISE EXCEPTION 'Template snapshot changed: support_ticket_created'; END IF;
